import type { IPpuApi } from "../../src/types/plugin";
import { parseBlockCharData, parseStageBlockData, type BlockData, type StageBlockItem } from "./bg";
import { StageContext } from "./common";
import { EnemyDagum, EnemyDee01, EnemyDucker, EnemyFan, EnemyGarun, EnemyJumper, EnemyRuguru, type EnemyManager } from "./enemy";
import type { PlayerData } from "./player";
import chrBlock from './data/chara1.csv?raw';
import spaceBlock from './data/space.csv?raw';

export type EventProp = Record<string, number>;

export interface EventData {
    // 進捗状況
    progress: number;
    // イベント種別
    name: string;
    // イベントパラメータ
    params: EventProp;
    // スクロールを待つか
    wait: boolean;
}
export interface StageEventData {
    checkPoint: {
        progress: number;
        romIndex: number;
    }[];
    eventList: EventData[];
    blockList: StageBlockItem[];
}

export interface IEventProc {
    /**
     * 戻り値が false になったら終了
     * @param context 
     * @param player 
     * @param enemy 
     */
    execute(context: StageContext, player: PlayerData, enemy: EnemyManager): boolean;
}

export function parseEventData(text: string): EventData[] {
    const result: EventData[] = [];
    for (let line of text.split('\n')) {
        if (line.startsWith('#')) {
            // コメント
            continue;
        }
        const cols = line.split(',');
        if (cols.length < 2) {
            continue;
        }
        let wait = false;
        if (cols[1].startsWith('*')) {
            wait = true;
            cols[1] = cols[1].substring(1);
        }
        const dt: EventData = {
            name: cols[1],
            progress: parseInt(cols[0]),
            params: {},
            wait: wait
        };
        if (cols[0].startsWith('+')) {
            // 相対
            if (result.length > 0) {
                dt.progress += result[result.length - 1].progress;
            }
        }
        for (let i = 2; i < cols.length; i++) {
            const ix = cols[i].indexOf('=');
            if (ix > 0) {
                dt.params[cols[i].substring(0, ix)] = parseInt(cols[i].substring(ix + 1));
            } else {
                const val = parseInt(cols[i]);
                if (isNaN(val)) {
                    console.error("event error:", cols[i], line);
                } else {
                    dt.params[i - 2] = val;
                }
            }
        }
        result.push(dt);
    }
    result.sort((v1, v2) => v1.progress - v2.progress);
    return result;
}
let eventProcMap: { [name: string]: (params: { [key: string]: number; }) => IEventProc } = {};

export function entryEvent(name: string, proc: (params: EventProp) => IEventProc): void {
    eventProcMap[name] = proc;
}

export class StageEventManager {
    context: StageContext;
    event?: {
        current: IEventProc;
        wait: boolean;
    };
    eventList: EventData[];
    stageBlock: StageBlockItem[];
    nextBlock: number;

    static spaceMap: StageBlockItem = parseStageBlockData(spaceBlock, parseBlockCharData(chrBlock))[0];

    public constructor(data: StageEventData, start: number) {
        this.context = new StageContext();
        let point = data.checkPoint[0];
        data.checkPoint.forEach(chk => {
            if (chk.progress <= start) {
                point = chk;
            }
        });
        this.eventList = data.eventList.filter(evt => evt.progress >= point.progress).sort((v1, v2) => v1.progress - v2.progress);
        this.stageBlock = data.blockList;
        this.context.progress = point.progress;
        this.context.chrRomIndex = point.romIndex;
        this.nextBlock = 0;
    }

    private drawBlock(ppu: IPpuApi, bx: number, blocks: BlockData[]): void {
        const name = ppu.getNameTable((bx & 16) >> 4);
        let lx = (bx & 15) * 2;
        const flags = this.context.blockFlags[bx % 32];
        let blk1 = "";
        let blk2 = "";
        for (let i = 0; i < blocks.length; i++) {
            const blk = blocks[i];
            if (blk) {
                name.print(lx, i * 2 + 2, blk.data).setColor(lx, 2 + i * 2, blk.palette);
                // 上位ビットはパレット
                flags[i] = blk.flag | (blk.palette << 4);
                blk1 += blk.data[0][0] + blk.data[1][0];
                blk2 += blk.data[0][1] + blk.data[1][1];
            }
        }
        this.context.bgText[(bx & 31) * 2] = blk1;
        this.context.bgText[(bx & 31) * 2 + 1] = blk2;
    }
    private getStageBlock(bx: number): BlockData[] {
        let result: BlockData[] = StageEventManager.spaceMap.data[bx % StageEventManager.spaceMap.data.length];
        for (let item of this.stageBlock) {
            if (item.start > bx) {
                break;
            }
            let ix = (bx - item.start) % item.data.length;
            result = item.data[ix];
        }
        return result;
    }

    public stepFrame(ppu: IPpuApi, player: PlayerData, enemy: EnemyManager): void {
        let bx = this.context.progress >> 4;
        for (let ix = 0; ix < 20; ix++) {
            if (bx >= this.nextBlock) {
                this.drawBlock(ppu, bx, this.getStageBlock(bx));
                this.nextBlock = bx + 1;
            }
            bx++;
        }
        let step = true;
        if (this.event) {
            if (this.event.current.execute(this.context, player, enemy)) {
                step = !this.event.wait;
            } else {
                this.event = undefined;
            }
        }
        if (step) {
            this.context.step();
            while (this.eventList.length > 0) {
                if (this.eventList[0].progress > this.context.progress) {
                    break;
                }
                const evt = this.eventList.splice(0, 1)[0];
                const proc = eventProcMap[evt.name];
                if (proc) {
                    const obj = proc(evt.params);
                    if (obj) {
                        if (obj.execute(this.context, player, enemy)) {
                            // 続きがある
                            this.event = {
                                current: obj,
                                wait: evt.wait
                            };
                            break;
                        }
                    }
                } else {
                    console.error("Unknown Event Name", evt.name);
                }
            }
        } else {
            this.context.scroll = false;
        }
    }
}

entryEvent("fan", ({ y, count }) => ({
    execute: (_context, _player, enemy) => {
        const data = { count: count || 4 };
        for (let i = 0; i < data.count; i++) {
            enemy.entry(new EnemyFan(256 + i * 22, y, data));
        }
        return false;
    }
}));

