entryEvent("volcano", ({ x, y, rev, count }) => {
    console.log("Volcano", x, y, rev, count);
    return {
        execute: (context, _player, _enemy) => {
            if (context.scroll) {
                x--;
            }
            count--;
            return count > 0;
        }
    }
});