import { RomEntry, type GameContext, type IFamRom } from "../../src/types/plugin";
import { chrRomMap } from "./common";
import memText from './memory.txt?raw';
import { TitleMode } from "./title";

@RomEntry("グラディウス")
// @ts-expect-error Registered by the RomEntry decorator.
class Gradius implements IFamRom {
    powerOn(context: GameContext): void {
        const mem = new Map<string, Uint8Array>([
            ...context.util.parseMemoryText(memText),
        ]);
        chrRomMap.splice(0, chrRomMap.length, ...[...mem.values()].map(data => {
            return context.ppu.makeChrRom(data);
        }));
        this.reset(context);
    }
    reset(context: GameContext): void {
        context.ppu.setMirrorMode('fourScreen');
        context.ppu.setControllData({
            spriteSize: 16,
            bgEnabled: false,
            spriteEnabled: false,
            bgPatternTableIndex: 0,
            bgClippingDisabled: false,
            spritePatternTableIndex: 1,
            spriteClippingDisabled: false
        });
        context.pushMode(new TitleMode());
    }
}
