import { ButtonType, SPRITE_BG_PRIORITY, SPRITE_HORIZONTAL_FLIP, SPRITE_VERTICAL_FLIP, type IPadApi } from "../../src/types/plugin";
import { playerSprite, playerSpriteDown, playerSpriteUp, StageContext, type HitTest, type SpriteGroup, type SpriteItem } from "./common";
import type { EnemyBase } from "./enemy";

// レーザーの当たり判定で分割されるサイズ
const LASER_SEGMENT = 16;

// レーザーの最大の長さ
const LASER_MAX_LENGTH = 12;
const LASER_WAIT = 24;

const MissleFlag = {
    NORMAL: 1,
    MISSLE: 2,
    DOUBLE: 4,
    LASER: 8
};

const MoveLimit = {
    Top: 16 << 4,
    Left: 8 << 4,
    Right: 232 << 4,
    Bottom: 192 << 4
};

class MissleData {
    sprite: SpriteGroup;
    flag: number;
    normal: {
        x: number;
        y: number;
    }[] = [];
    missle: {
        x: number;
        y: number;
        dir: number;
    }[] = [];
    double: {
        x1: number;
        y1: number;
        x2: number;
        y2: number;
    }[] = [];
    laser: {
        dx: number;
    }[] = [];
    pushCount: {
        normal: number;
        missle: number;
    } = {
            normal: 0,
            missle: 0,
        };
    clock: number;
    hitTest: HitTest[] = [];
    hitCallback: { [id: string]: (enemy?: EnemyBase) => boolean; } = {};
    prefix: string;

    public constructor(prefix: string) {
        this.prefix = prefix;
        this.flag = MissleFlag.NORMAL;
        this.clock = 0;
        this.sprite = {
            x: 0,
            y: 0,
            horizontalFlip: false,
            verticalFlip: false,
            items: []
        };
    }
    private addHitTest(hitTest: HitTest, callback: (enemy?: EnemyBase) => boolean): void {
        this.hitTest.push({
            ...hitTest,
            id: this.prefix + hitTest.id
        });
        this.hitCallback[this.prefix + hitTest.id] = callback;
    }
    public onHitTest(id: string, enemy?: EnemyBase): boolean {
        if (this.hitCallback[id]) {
            return this.hitCallback[id](enemy);
        }
        return false;
    }
    private moveStep(stage: StageContext, pos: { x: number; y: number; }): void {
        this.hitCallback = {};
        this.hitTest = [];
        const items: SpriteItem[] = [];
        this.normal = this.normal.filter((dt, ix) => {
            dt.x += 7;
            if (dt.x >= 256) {
                return false;
            }
            items.push({
                dx: dt.x,
                dy: dt.y,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x6b
            });
            this.addHitTest({
                x: dt.x,
                y: dt.y - 2,
                width: 8,
                height: 4,
                id: "n" + ix,
                type: "missle"
            }, () => {
                dt.x = 256;
                return true;
            });
            return true;
        });
        this.missle = this.missle.filter((dt, ix) => {
            if (stage.isBlock(dt.x + 4, dt.y + 6)) {
                dt.dir = 0;
                dt.x += 2;
            } else {
                dt.dir = 1;
                dt.x += 1;
                dt.y += 2;
            }
            if (dt.x >= 256 || dt.y >= 208) {
                return false;
            }
            if (dt.dir < 0) {
                items.push({
                    dx: dt.x,
                    dy: dt.y,
                    attributes: 2 | SPRITE_VERTICAL_FLIP | SPRITE_BG_PRIORITY,
                    tileIndex: 0x65
                });
            } else if (dt.dir > 0) {
                items.push({
                    dx: dt.x,
                    dy: dt.y,
                    attributes: 2 | SPRITE_BG_PRIORITY,
                    tileIndex: 0x65
                });
            } else {
                items.push({
                    dx: dt.x,
                    dy: dt.y,
                    attributes: 2 | SPRITE_BG_PRIORITY,
                    tileIndex: 0x61
                });
            }
            this.addHitTest({
                x: dt.x,
                y: dt.y,
                width: 8,
                height: 8,
                id: "m" + ix,
                type: "missle"
            }, () => {
                dt.x = 256;
                return true;
            });
            return true;
        });
        this.double = this.double.filter((dt, ix) => {
            dt.x1 += 7;
            dt.x2 += 5;
            dt.y2 -= 5;
            let cont = false;
            if (dt.x1 < 256) {
                cont = true;
                items.push({
                    dx: dt.x1,
                    dy: dt.y1,
                    attributes: 2 | SPRITE_BG_PRIORITY,
                    tileIndex: 0x6b
                });
                this.addHitTest({
                    x: dt.x1,
                    y: dt.y1 - 2,
                    width: 8,
                    height: 4,
                    id: "d" + ix,
                    type: "missle"
                }, () => {
                    dt.x1 = 256;
                    return true;
                });
            }
            if (dt.x2 < 256 && dt.y2 > 0) {
                cont = true;
                items.push({
                    dx: dt.x2,
                    dy: dt.y2,
                    attributes: 2 | SPRITE_BG_PRIORITY,
                    tileIndex: 0x73
                });
                this.addHitTest({
                    x: dt.x2,
                    y: dt.y2,
                    width: 8,
                    height: 8,
                    id: "du" + ix,
                    type: "missle"
                }, () => {
                    dt.x2 = 256;
                    return true;
                });
            }
            return cont;
        });
        this.laser = this.laser.filter((dt, ix) => {
            dt.dx += 8;
            let ex = pos.x + dt.dx;
            let sx = Math.max(pos.x + 8, ex - LASER_SEGMENT);
            if (sx >= 256) {
                return false;
            }
            stage.addLaserDraw({
                y: pos.y,
                lines: [
                    {
                        sx: sx,
                        ex: ex
                    }
                ]
            });
            this.addHitTest({
                x: sx,
                y: pos.y - 2,
                width: ex - sx,
                height: 4,
                id: "l" + ix,
                block: {
                    x: ex - 4,
                    y: pos.y
                },
                type: "laser"
            }, (enemy) => {
                if (enemy) {
                    if (enemy.hasShield()) {
                        dt.dx = 256 + LASER_SEGMENT;
                        return true;
                    }
                } else {
                    dt.dx = 256 + LASER_SEGMENT;
                    return true;
                }
                return false;
            });
            return true;
        });
        // 1つづつずらす
        this.sprite.items = items.map((_itm, ix) => {
            return items[(ix + this.clock) % items.length];
        });
    }
    public step(stage: StageContext, push: boolean, pos: { x: number; y: number; }): void {
        this.clock++;
        if (!push) {
            this.pushCount = {
                normal: 0,
                missle: 0
            };
        }
        if (push) {
            if (this.flag & MissleFlag.NORMAL) {
                if (this.pushCount.normal === 0 || this.pushCount.normal > 30) {
                    if (this.normal.length < 2) {
                        // 発射する
                        this.normal.push({
                            x: pos.x,
                            y: pos.y
                        });
                        this.pushCount.normal = 0;
                    }
                }
                this.pushCount.normal++;
            }
            if (this.flag & MissleFlag.MISSLE) {
                if (this.pushCount.missle === 0 || this.pushCount.missle > 40) {
                    if (this.missle.length < 1) {
                        this.missle.push({
                            x: pos.x,
                            y: pos.y,
                            dir: 1
                        });
                        this.pushCount.missle = 0;
                    }
                }
                this.pushCount.missle++;
            }
            if (this.flag & MissleFlag.DOUBLE) {
                if (this.pushCount.normal === 0 || this.pushCount.normal > 30) {
                    if (this.double.length < 2) {
                        // 発射する
                        this.double.push({
                            x1: pos.x,
                            y1: pos.y,
                            x2: pos.x,
                            y2: pos.y
                        });
                        this.pushCount.normal = 0;
                    }
                }
                this.pushCount.normal++;
            }
            if (this.flag & MissleFlag.LASER) {
                if (this.laser.length === 0 || this.laser[0].dx >= LASER_SEGMENT + 16) {
                    if (this.pushCount.normal < LASER_MAX_LENGTH) {
                        this.laser = [{
                            dx: 16
                        }, ...this.laser];
                        this.pushCount.normal++;
                    } else if (this.pushCount.normal > LASER_MAX_LENGTH + LASER_WAIT) {
                        this.pushCount.normal = 0;
                    } else {
                        this.pushCount.normal++;
                    }
                }
            }
        }
        this.moveStep(stage, pos);
    }
}

/**
 * 追跡データ
 * 最初のオプションは16遅れ
 * 次からは17遅れ
 */
class TraceData {
    trace: {
        x: number;
        y: number;
    }[];
    child: TraceData | null;
    private limit: number;

    public constructor(limit: number) {
        this.trace = [];
        this.child = null;
        this.limit = limit;
    }
    public add(x: number, y: number): void {
        this.trace.push({
            x: x,
            y: y
        });
        if (this.trace.length > this.limit) {
            if (this.child) {
                this.child.add(this.trace[0].x, this.trace[0].y);
            }
            this.trace.splice(0, 1);
        }
    }
    public addChild(child: TraceData): void {
        this.child = child;
        if (this.trace.length > 0) {
            child.add(this.trace[0].x, this.trace[0].y);
        }
    }
    public set(pos: { x: number; y: number; }): void {
        if (this.trace.length > 0) {
            pos.x = this.trace[this.trace.length - 1].x;
            pos.y = this.trace[this.trace.length - 1].y;
        }
    }
}
class OptionData {
    trace: TraceData[];
    position: {
        x: number;
        y: number;
    }[];
    sprite: SpriteGroup;
    missle: MissleData[];
    clock: number;
    parent: TraceData;

    public constructor(parent: TraceData) {
        this.position = [];
        this.parent = parent;
        this.missle = [];
        this.trace = [];
        this.clock = 0;
        this.sprite = {
            x: 0,
            y: 0,
            horizontalFlip: false,
            verticalFlip: false,
            items: []
        };
    }
    public addOption(groups: SpriteGroup[]): void {
        if (this.trace.length >= 4) {
            return;
        }
        const tr = new TraceData(12);
        if (this.trace.length > 0) {
            this.trace[this.trace.length - 1].addChild(tr);
        } else {
            this.parent.addChild(tr);
        }
        const pos = { x: 0, y: 0 };
        tr.set(pos);
        this.position.push(pos);
        this.trace.push(tr);
        this.missle.push(new MissleData("option" + this.missle.length + "_"));
        groups.push(this.missle[this.missle.length - 1].sprite);
    }
    public step(stage: StageContext, push: boolean): void {
        this.clock++;
        const tile = (this.clock & 8) ? 0x5b : 0x59;
        this.sprite.items = [];
        for (let i = 0; i < this.trace.length; i++) {
            this.trace[i].set(this.position[i]);
            this.missle[i].step(stage, push, {
                x: this.position[i].x,
                y: this.position[i].y + 6
            });
        }
        const item1: SpriteItem[] = [];
        const item2: SpriteItem[] = [];
        for (let i = 0; i < this.trace.length; i++) {
            const ix = (i + this.clock) % this.trace.length;
            item1.push({
                attributes: 3 | SPRITE_BG_PRIORITY,
                tileIndex: tile,
                dx: this.position[ix].x,
                dy: this.position[ix].y
            });
            item2.push({
                attributes: SPRITE_HORIZONTAL_FLIP | 3 | SPRITE_BG_PRIORITY,
                tileIndex: tile,
                dx: this.position[ix].x + 8,
                dy: this.position[ix].y
            });
        }
        if (this.clock & 1) {
            this.sprite.items = [...item1, ...item2];
        } else {
            this.sprite.items = [...item2, ...item1];
        }
    }
}

export class PlayerData {
    sprite: SpriteGroup;
    private missle: MissleData;
    private trace: TraceData;
    private options: OptionData;
    private position: {
        x: number;
        y: number;
        speed: number;
    } = {
            x: 72 << 4,
            y: 96 << 4,
            speed: 16
        };
    powerLevel = 0;
    barrierCount = 0;
    missCount = 0;

    public constructor() {
        this.sprite = {
            x: this.position.x >> 4,
            y: this.position.y >> 4,
            horizontalFlip: false,
            verticalFlip: false,
            items: playerSprite
        };
        this.missle = new MissleData("player_");
        this.trace = new TraceData(12);
        this.trace.add(this.sprite.x, this.sprite.y);
        this.options = new OptionData(this.trace);
    }

    public initSprite(groups: SpriteGroup[]): void {
        groups.push(
            this.sprite,
            this.missle.sprite,
            this.options.sprite,
            ...this.options.missle.map(m => m.sprite)
        );
    }

    private powerUp(groups: SpriteGroup[]): void {
        if (!(this.getCupsuleFlag() & (1 << (this.powerLevel - 1)))) {
            return;
        }
        switch (this.powerLevel) {
            case 1:
                this.position.speed += 8;
                break;
            case 2:
                this.missle.flag |= MissleFlag.MISSLE;
                break;
            case 3:
                this.missle.flag |= MissleFlag.DOUBLE;
                this.missle.flag &= ~(MissleFlag.NORMAL | MissleFlag.LASER);
                break;
            case 4:
                this.missle.flag &= ~(MissleFlag.NORMAL | MissleFlag.DOUBLE);
                this.missle.flag |= MissleFlag.LASER;
                break;
            case 5:
                this.options.addOption(groups);
                break;
            case 6:
                this.barrierCount = 5;
                break;
        }
        this.options.missle.forEach(ms => ms.flag = this.missle.flag);
        this.powerLevel = 0;
    }
    public stepFrame(stage: StageContext, pad: IPadApi, groups: SpriteGroup[]): HitTest[] {
        if (this.missCount > 0) {
            this.missCount++;
            this.missle.step(stage, false, {
                x: this.sprite.x,
                y: this.sprite.y + 6
            });
            this.options.step(stage, false);

            let result: HitTest[] = [...this.missle.hitTest];
            this.options.missle.forEach(m => result.push(...m.hitTest));
            return result;
        }
        let move = false;
        let speed = this.position.speed;
        if (this.powerLevel > 0 && pad.isPush(ButtonType.B)) {
            this.powerUp(groups);
        }
        if (pad.isDown(ButtonType.DOWN)) {
            this.sprite.items = playerSpriteDown;
            if (this.position.y < MoveLimit.Bottom) {
                this.position.y += speed;
                if (this.position.y > MoveLimit.Bottom) {
                    this.position.y = MoveLimit.Bottom;
                }
            }
            move = true;
        } else if (pad.isDown(ButtonType.UP)) {
            this.sprite.items = playerSpriteUp;
            if (this.position.y > MoveLimit.Top) {
                this.position.y -= speed;
                if (this.position.y < MoveLimit.Top) {
                    this.position.y = MoveLimit.Top;
                }
            }
            move = true;
        } else {
            this.sprite.items = playerSprite;
        }
        if (pad.isDown(ButtonType.LEFT)) {
            if (this.position.x > MoveLimit.Left) {
                this.position.x -= speed;
                if (this.position.x < MoveLimit.Left) {
                    this.position.x = MoveLimit.Left;
                }
            }
            move = true;
        } else if (pad.isDown(ButtonType.RIGHT)) {
            if (this.position.x < MoveLimit.Right) {
                this.position.x += speed;
                if (this.position.x > MoveLimit.Right) {
                    this.position.x = MoveLimit.Right;
                }
            }
            move = true;
        }
        this.sprite.x = this.position.x >> 4;
        this.sprite.y = this.position.y >> 4;
        if (move) {
            this.trace.add(this.sprite.x, this.sprite.y);
        }
        this.missle.step(stage, pad.isDown(ButtonType.A) > 0, {
            x: this.sprite.x,
            y: this.sprite.y + 6
        });
        this.options.step(stage, pad.isDown(ButtonType.A) > 0);

        let result: HitTest[] = [...this.missle.hitTest];
        this.options.missle.forEach(m => result.push(...m.hitTest));
        // 自分自身
        result.push({
            x: this.sprite.x + 4,
            y: this.sprite.y + 5,
            width: 12,
            height: 6,
            id: "player",
            type: this.barrierCount > 0 ? "barrier" : "player"
        });
        return result;
    }
    public onGetCupsule(): void {
        this.powerLevel++;
        if (this.powerLevel > 6) {
            this.powerLevel = 1;
        }
    }
    public onHitTest(hit: HitTest, enemy?: EnemyBase): boolean {
        if (hit.type === "erase") {
            return false;
        } else if (hit.type === "barrier") {
            this.barrierCount--;
            if (this.barrierCount === 0) {
                hit.type = "player";
            }
            return false;
        } else if (hit.type === "player") {
            // ミス
            this.missCount = 1;
            return true;
        } else if (hit.id.startsWith(this.missle.prefix)) {
            return this.missle.onHitTest(hit.id, enemy);
        } else {
            for (let ms of this.options.missle) {
                if (hit.id.startsWith(ms.prefix)) {
                    return ms.onHitTest(hit.id, enemy);
                }
            }
        }
        return false;
    }
    public getCupsuleFlag(): number {
        let result = 15;
        if (this.missle.flag & MissleFlag.MISSLE) {
            result &= ~2;
        }
        if (this.missle.flag & MissleFlag.DOUBLE) {
            result &= ~4;
        }
        if (this.missle.flag & MissleFlag.LASER) {
            result &= ~8;
        }
        if (this.options.trace.length < 4) {
            result |= 16;
        }
        if (this.barrierCount === 0) {
            result |= 32;
        }
        return result;
    }
}