import { ButtonType, type GameContext, type IGameMode } from "../../src/types/plugin";
import { chrRomMap, getTextCode, makeCharMap, playerSprite, writeSprites } from "./common";
import { stage1Data } from "./data/stage1";
import { PlayMode } from "./play";
import { PlayerData } from "./player";

const titleCode = [
    [0x80, 0x81, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x82, 0x83, 0x84],
    [0x85, 0x86, 0x87, 0x88, 0x89, 0x8a, 0x8a, 0x8a, 0x8b, 0x8c, 0x8d, 0x8e, 0x8f, 0x90, 0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x8a, 0x8a, 0x8a, 0x97, 0x88, 0x98, 0x99, 0x9a],
    [0xbb, 0x86, 0x87, 0x88, 0x9c, 0x9d, 0x9e, 0x9f, 0xa0, 0xa1, 0xa2, 0xa3, 0xa4, 0xa5, 0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab, 0xac, 0x9c, 0x88, 0x98, 0x99, 0x9b],
    [0xbb, 0x86, 0x87, 0x88, 0xad, 0xae, 0xaf, 0xb0, 0xb1, 0xb2, 0xb3, 0xb4, 0xb5, 0xb6, 0xb6, 0xb7, 0xaf, 0xb8, 0xb9, 0xba, 0x88, 0x98, 0x99, 0x9b],
    [0xbb, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0xbc, 0x9b]
];

const charMap: { [ch: string]: number; } = {
    ...makeCharMap(0, " GAMEOVRLYSCTDKNHI"),
    ...makeCharMap(0x1c, "UW'X"),
    ...makeCharMap(0x30, "0123456789"),
    '@': 0x61,
    'P': 0x66,
    'Z': 0xbe,
    '!': 0xbf,
    'B': 0xc6
};

export class TitleMode implements IGameMode {
    private scrollX = 255;

    onEnter(context: GameContext, _prev?: IGameMode): void {
        this.scrollX = 255;
        chrRomMap[3].set(0);
        context.ppu.setControllData({
            bgEnabled: true,
            spriteEnabled: true,
            nameTableIndex: 0
        });
        writeSprites(context.ppu, []);
        context.ppu.setScroll(0, 0);
        for (let i = 0; i < 2; i++) {
            const name = context.ppu.getNameTable(i);
            for (let j = 0; j < 0x3c0 + 32; j++) {
                name.write(j, 0);
            }
        }
        const name = context.ppu.getNameTable(0);
        name.print(12, 4, [
            String.fromCharCode(0xc0, 0xc1, 0, 0, 0, 0, 0xc0),
            String.fromCharCode(0xd0, 0xd1, 0xd2, 0xd3, 0xd0, 0xd1, 0xd2, 0xd3),
        ]);
        name.setColor(16, 4, 1).setColor(18, 4, 1);
        for (let y = 0; y < titleCode.length; y++) {
            const row = titleCode[y];
            name.print(y + 1, y + 8, row);
            for (let x = 0; x < row.length; x++) {
                name.setColor(y + 1 + x, y + 8, 3);
            }
        }
        name.print(9, 15, getTextCode(charMap, "@ KONAMI 1986"));
        name.print(10, 20, getTextCode(charMap, "PLAY. SELECT"));
        name.print(13, 22, getTextCode(charMap, "1 PLAYER"));
        name.print(13, 24, getTextCode(charMap, "2 PLAYER"));
        context.ppu.getPalette().writeBytes(0,
            new Uint8Array([
                0x0f, 0x30, 0x30, 0x0f,
                0x0f, 0x0f, 0x30, 0x30,
                0x0f, 0x26, 0x06, 0x1c,
                0x0f, 0x35, 0x16, 0x1c,
                0x0f, 0x0c, 0x26, 0x30,
                0x0f, 0x0c, 0x2c, 0x30,
                0x0f, 0x12, 0x26, 0x30,
                0x0f, 0x06, 0x0f, 0x30
            ])
        );
    }
    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        if (this.scrollX > 0) {
            this.scrollX -= 2;
            if (pad.isPush(ButtonType.START) || this.scrollX <= 0) {
                this.scrollX = 0;
                writeSprites(context.ppu, [{
                    x: 0x48,
                    y: 0xae,
                    horizontalFlip: false,
                    verticalFlip: false,
                    items: playerSprite
                }]);
            }
            context.ppu.setScroll(this.scrollX, 0);
            return;
        }
        if (pad.isPush(ButtonType.START)) {
            context.moveMode(new PlayMode(new PlayerData(),stage1Data));
        }
    }
}