import { SPRITE_BG_PRIORITY, SPRITE_HORIZONTAL_FLIP, SPRITE_VERTICAL_FLIP } from "../../src/types/plugin";
import type { HitTest, SpriteGroup, SpriteItem, StageContext } from "./common";


export abstract class EnemyBase {
    sprite: SpriteGroup;
    spriteItems: SpriteItem[] = [];
    clock: number;

    protected constructor() {
        this.sprite = {
            x: 0,
            y: 0,
            horizontalFlip: false,
            verticalFlip: false,
            items: []
        };
        this.clock = 0;
    }

    public stepFrame(manager: EnemyManager, stage: StageContext): void {
        this.onStepFrame(manager, stage);
        this.clock++;
        this.sprite.items = this.spriteItems.map((_itm, ix) => this.spriteItems[(ix + this.clock) % this.spriteItems.length]);
    }
    protected abstract onStepFrame(manager: EnemyManager, stage: StageContext): void;
    public entry(group: SpriteGroup[]): void {
        group.push(this.sprite);
    }
    public leave(group: SpriteGroup[]): void {
        let ix = group.indexOf(this.sprite);
        if (ix >= 0) {
            group.splice(ix, 1);
        }
    }
    public checkHit(manager: EnemyManager, hit: HitTest): boolean {
        if (this.sprite.width && this.sprite.height) {
            if (this.sprite.x < hit.x + hit.width && hit.x < this.sprite.x + this.sprite.width && this.sprite.y < hit.y + hit.height && hit.y < this.sprite.y + this.sprite.height) {
                this.onHit(manager, hit);
                return true;
            }
        }
        return false;
    }
    protected onHit(_manager: EnemyManager, _hit: HitTest): void {
    }
    /**
     * 初期セットアップ
     * @param _stage 
     */
    public setup(_stage: StageContext): void {

    }
    /**
     * レーザーを止めるシールドがあるか？
     * @returns 
     */
    public hasShield(): boolean {
        return false;
    }
}

