export class EnemyManager {
    private enemyList: EnemyBase[] = [];
    private entryList: EnemyBase[] = [];
    private removeList: EnemyBase[] = [];
    cupsules: {
        x: number;
        y: number;
    }[] = [];
    bombers: {
        x: number;
        y: number;
        type: "small" | "normal" | "large";
    }[] = [];
    plusPoint: number;
    missle: EnemyMissle;

    public constructor() {
        this.plusPoint = 0;
        this.missle = new EnemyMissle();
    }
    public entry(enemy: EnemyBase): EnemyManager {
        this.entryList.push(enemy);
        return this;
    }
    public remove(enemy: EnemyBase): EnemyManager {
        this.removeList.push(enemy);
        return this;
    }

    public stepFrame(stage: StageContext, groups: SpriteGroup[], hits: HitTest[], callback: (hit: HitTest, enemy?: EnemyBase) => boolean): void {
        this.cupsules = [];
        this.bombers = [];
        this.plusPoint = 0;
        for (let ene of this.enemyList) {
            ene.stepFrame(this, stage);
            let del: HitTest[] = [];
            for (let hit of hits) {
                if (this.removeList.includes(ene)) {
                    break;
                }
                if (ene.checkHit(this, hit)) {
                    if (callback(hit, ene)) {
                        del.push(hit);
                    }
                }
            }
            if (del.length > 0) {
                // 削除
                for (let e of del) {
                    let ix = hits.indexOf(e);
                    if (ix >= 0) {
                        hits.splice(ix, 1);
                    }
                }
            }
        }
        // ミサイル
        this.missle.stepFrame(this, stage);
        for (let hit of hits) {
            if (this.missle.checkHit(this, hit)) {
                if (callback(hit, this.missle)) {
                    // 消える
                    hits.splice(hits.indexOf(hit), 1);
                    break;
                }
            }
        }
        // ブロックに当たる判定
        for (let hit of hits) {
            const pos = hit.block || {
                x: hit.x + hit.width / 2,
                y: hit.y + hit.height / 2
            };
            if (stage.isBlock(pos.x, pos.y)) {
                callback(hit);
            }
        }
        this.removeList.forEach(e => {
            e.leave(groups);
            let ix = this.enemyList.indexOf(e);
            if (ix >= 0) {
                this.enemyList.splice(ix, 1);
            }
        });
        this.entryList.forEach(e => {
            e.setup(stage);
            e.entry(groups);
            this.enemyList.push(e);
        });
        this.entryList = [];
        this.removeList = [];
    }
    public dropCupsule(x: number, y: number): EnemyManager {
        this.cupsules.push({ x, y });
        return this;
    }
    public addBomb(x: number, y: number, type: "small" | "normal" | "large"): EnemyManager {
        this.bombers.push({ x, y, type });
        return this;
    }
    public addPoint(point: number): EnemyManager {
        this.plusPoint += point;
        return this;
    }
    public addMissle(stage: StageContext, from: { x: number; y: number }): void {
        this.missle.addMissle(stage, from);
    }
}

