export class EnemyFan extends EnemyBase {
    // mode:0 (-2,0) x=94まで, mode1:(1,2), mode2:(1,-2), mode3:(2,0)
    mode: number;
    data: {
        count: number;
    };
    static spriteItems: SpriteItem[][] = [
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x15
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x17
            },
        ],
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x19
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x1b
            }
        ],
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2,
                tileIndex: 0x17 | SPRITE_VERTICAL_FLIP | SPRITE_HORIZONTAL_FLIP | SPRITE_BG_PRIORITY
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_VERTICAL_FLIP | SPRITE_HORIZONTAL_FLIP | SPRITE_BG_PRIORITY,
                tileIndex: 0x15
            },
        ],
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_VERTICAL_FLIP | SPRITE_HORIZONTAL_FLIP | SPRITE_BG_PRIORITY,
                tileIndex: 0x1b
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_VERTICAL_FLIP | SPRITE_HORIZONTAL_FLIP | SPRITE_BG_PRIORITY,
                tileIndex: 0x19
            },
        ]
    ];

    /**
     * 
     * @param x
     * @param y 42 or 160
     * @param data 
     */
    public constructor(x: number, y: number, data: { count: number; }) {
        super();
        this.sprite.x = x;
        this.sprite.y = y;
        this.data = data;
        this.mode = 0;
        // y = 42,160
        this.spriteItems = EnemyFan.spriteItems[0];
    }
    protected onStepFrame(manager: EnemyManager, stage: StageContext): void {
        // 15:17, 19:1b, *17:*15, *19:*1b
        this.spriteItems = EnemyFan.spriteItems[Math.floor(this.clock / 6) % 4];
        if (this.mode === 0) {
            this.sprite.x -= 2;
            if (this.sprite.x <= 94) {
                if (this.sprite.y < 128) {
                    this.mode = 1;
                } else {
                    this.mode = 2;
                }
            }
        } else if (this.mode === 1) {
            // 限界 y = 32,170
            this.sprite.x++;
            this.sprite.y += 2;
            if (this.sprite.y >= 170 || this.sprite.y > stage.playerPos.y) {
                this.mode = 3;
            }
        } else if (this.mode === 2) {
            this.sprite.x++;
            this.sprite.y -= 2;
            if (this.sprite.y <= 32 || this.sprite.y < stage.playerPos.y) {
                this.mode = 3;
            }
        } else {
            this.sprite.x += 2;
            if (this.sprite.x >= 256) {
                manager.remove(this);
            }
        }
    }
    protected onHit(manager: EnemyManager, _hit: HitTest): void {
        manager.remove(this).addBomb(this.sprite.x, this.sprite.y, "small").addPoint(100);
        this.data.count--;
        if (this.data.count === 0) {
            manager.dropCupsule(this.sprite.x, this.sprite.y);
        }
    }
}

class EnemyMissle extends EnemyBase {
    private missles: {
        x: number;
        y: number;
        ax: number;
        ay: number;
    }[] = [];

    public constructor() {
        super();
        this.sprite.x = 0;
        this.sprite.y = 0;
        this.sprite.width = 0;
        this.sprite.height = 0;
    }
    protected onStepFrame(_manager: EnemyManager, stage: StageContext): void {
        this.spriteItems = [];
        let delList: any[] = [];
        for (let i = 0; i < this.missles.length; i++) {
            const ms = this.missles[(i + this.clock) % this.missles.length];
            ms.x += ms.ax;
            ms.y += ms.ay;
            let x = ms.x >> 4;
            let y = ms.y >> 4;
            if (x <= 0 || x >= 256 || y <= -8 || y >= 208) {
                // 画面外
                delList.push(ms);
            } else {
                //if (stage.isBlock(x, y) || stage.isBlock(x + 7, y) || stage.isBlock(x, y + 7) || stage.isBlock(x + 7, y + 7)) {
                if (stage.isBlock(x + 3, y + 3)) {
                    // 障害物に当たって消える
                    delList.push(ms);
                } else {
                    this.spriteItems.push({
                        dx: x,
                        dy: y,
                        attributes: 3 | SPRITE_BG_PRIORITY,
                        tileIndex: 0x69
                    });
                }
            }
        }
        for (let del of delList) {
            let ix = this.missles.indexOf(del);
            if (ix >= 0) {
                this.missles.splice(ix, 1);
            }
        }
    }
    public checkHit(_manager: EnemyManager, hit: HitTest): boolean {
        if (hit.type !== "player" && hit.type !== "barrier") {
            return false;
        }
        for (let ms of this.missles) {
            if ((ms.x >> 4) + 2 < hit.x + hit.width && hit.x < (ms.x >> 4) + 6 && (ms.y >> 4) + 2 < hit.y + hit.height && hit.y < (ms.y >> 4) + 6) {
                // 当たった
                if (hit.type === "barrier") {
                    this.missles.splice(this.missles.indexOf(ms), 1);
                }
                return true;
            }
        }
        return false;
    }

    public addMissle(stage: StageContext, from: { x: number; y: number }): void {
        let dx = stage.playerPos.x + 8 - from.x;
        let dy = stage.playerPos.y + 8 - from.y;
        if (dx === 0 && dy === 0) {
            dy = 1;
        }
        let len = Math.sqrt(dx * dx + dy * dy);
        let speed = len / 200 + 1;
        this.missles.push({
            x: from.x << 4,
            y: from.y << 4,
            ax: Math.round(dx * 16 * speed / len),
            ay: Math.round(dy * 16 * speed / len)
        });
    }
}
