export class EnemyRuguru extends EnemyBase {
    static spriteItems: SpriteItem[][] = [
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY | SPRITE_VERTICAL_FLIP,
                tileIndex: 0x31,
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY | SPRITE_VERTICAL_FLIP,
                tileIndex: 0x33
            }
        ],
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x6f
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x71
            }
        ],
        [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x31,
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x33
            }
        ],
    ];
    move: boolean;
    public constructor(x: number, y: number) {
        super();
        this.sprite.x = x;
        this.sprite.y = y;
        this.move = true;
        this.spriteItems = EnemyRuguru.spriteItems[0];
    }
    protected onStepFrame(manager: EnemyManager, stage: StageContext): void {
        if (this.sprite.y > stage.playerPos.y) {
            this.spriteItems = EnemyRuguru.spriteItems[2];
            this.sprite.x--;
            if (this.move) {
                this.sprite.y--;
            }
            this.move = !this.move;
        } else if (this.sprite.y < stage.playerPos.y) {
            this.spriteItems = EnemyRuguru.spriteItems[0];
            this.sprite.x--;
            if (this.move) {
                this.sprite.y++;
            }
            this.move = !this.move;
        } else {
            this.spriteItems = EnemyRuguru.spriteItems[1];
            this.sprite.x -= 2;
            this.move = true;
        }
        if (this.sprite.x <= -8) {
            manager.remove(this);
        }
    }

    protected onHit(manager: EnemyManager, _hit: HitTest): void {
        manager.remove(this).addBomb(this.sprite.x, this.sprite.y, "normal").addPoint(100);
    }
}

