export class EnemyGarun extends EnemyBase {
    startPos: {
        x: number;
        y: number;
    };
    power: boolean;

    public constructor(power: boolean, y: number) {
        super();
        this.startPos = {
            x: 256,
            y: y
        };
        this.power = power;
    }
    protected onStepFrame(manager: EnemyManager, _stage: StageContext): void {
        this.sprite.x = this.startPos.x - this.clock * 2;
        this.sprite.y = this.startPos.y + Math.round(Math.sin(this.clock * Math.PI / 30) * 20);
        const ch = (Math.floor(this.clock / 6) % 4) * 4 + 0x1d;
        const attr = (this.power ? 3 : 2) | SPRITE_BG_PRIORITY;
        this.spriteItems = [
            {
                dx: 0,
                dy: 0,
                attributes: attr,
                tileIndex: ch
            },
            {
                dx: 8,
                dy: 0,
                attributes: attr,
                tileIndex: ch + 2
            }
        ];
        if (this.sprite.x <= -8) {
            manager.remove(this);
        }
    }
    protected onHit(manager: EnemyManager, _hit: HitTest): void {
        manager.remove(this).addBomb(this.sprite.x, this.sprite.y, "normal").addPoint(100);
        if (this.power) {
            manager.dropCupsule(this.sprite.x, this.sprite.y);
        }
    }
}

// die
export class EnemyDee01 extends EnemyBase {
    private timing: number;

    public constructor(y: number, reverse: boolean) {
        super();
        this.sprite.y = y;
        this.sprite.x = 256;
        // d7,cf d9,cf
        this.spriteItems = [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0xd7
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0xcf
            }
        ];
        this.sprite.verticalFlip = reverse;
        this.timing = 150;
    }
    protected onStepFrame(manager: EnemyManager, stage: StageContext): void {
        if (stage.scroll) {
            this.sprite.x--;
            if (this.sprite.x <= -8) {
                manager.remove(this);
                return;
            }
        }
        if (this.timing > 0 && this.clock > 0) {
            if (this.clock % this.timing === 0) {
                manager.addMissle(stage, {
                    x: this.sprite.x + 8,
                    y: this.sprite.y + 8
                });
            }
        }
        const dx = stage.playerPos.x - this.sprite.x;
        const dy = stage.playerPos.y - this.sprite.y;
        this.sprite.horizontalFlip = dx > 0;
        if (Math.abs(dx) * 4 < Math.abs(dy)) {
            this.spriteItems[0].tileIndex = 0xd9;
        } else {
            this.spriteItems[0].tileIndex = 0xd7;
        }
    }
    protected onHit(manager: EnemyManager, _hit: HitTest): void {
        manager.remove(this).addBomb(this.sprite.x, this.sprite.y, "normal").addPoint(100);
    }
}

export class EnemyDucker extends EnemyBase {
    // 1:右,0:砲台,-2:左
    private mode = 1;
    private count = 64;
    private rest = 4;

    public constructor(y: number, reverse: boolean) {
        super();
        this.sprite.y = y;
        this.sprite.x = -8;
        // d7,cf d9,cf
        this.spriteItems = [
            {
                dx: 0,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x3d
            },
            {
                dx: 8,
                dy: 0,
                attributes: 2 | SPRITE_BG_PRIORITY,
                tileIndex: 0x3f
            }
        ];
        this.sprite.verticalFlip = reverse;
    }
    protected onStepFrame(manager: EnemyManager, stage: StageContext): void {
        if (this.mode === 0) {
            if (stage.scroll) {
                this.sprite.x--;
            }
            // 砲台
            if (this.count === 25) {
                manager.addMissle(stage, {
                    x: this.sprite.x + 8,
                    y: this.sprite.y + 8
                });
            }
            this.count--;
            if (this.count === 0) {
                // 次の移動
                if (this.rest > 0) {
                    this.rest--;
                    if (this.sprite.x < 128) {
                        this.mode = 1;
                        this.count = 64;
                    } else {
                        if (stage.playerPos.x > this.sprite.x) {
                            this.mode = 1;
                            this.count = Math.ceil(stage.playerPos.x - this.sprite.x + 8);
                        } else {
                            this.mode = -2;
                            this.count = 48;
                        }
                    }
                } else {
                    this.mode = -2;
                    this.count = 128;
                }
            }
        } else {
            this.sprite.x += this.mode;
            if (this.sprite.x <= -8 && this.rest === 0) {
                manager.remove(this);
                return;
            }
            if (this.sprite.verticalFlip) {
                // 上
                if (stage.isBlock(this.sprite.x + 8, this.sprite.y + 2)) {
                    // 下に
                    this.sprite.y += 3;
                } else if (this.sprite.y > 19 && !stage.isBlock(this.sprite.x + 8, this.sprite.y - 1)) {
                    // 上に
                    this.sprite.y -= 3;
                }
            } else {
                if (stage.isBlock(this.sprite.x + 8, this.sprite.y + 14)) {
                    this.sprite.y -= 3;
                } else if (this.sprite.y < 180 && !stage.isBlock(this.sprite.x + 8, this.sprite.y + 16)) {
                    this.sprite.y += 3;
                }
            }
            this.count--;
            if (this.count === 0) {
                this.mode = 0;
                this.count = 50;
            }
        }
        if (this.mode === 0) {
            // 3d:3f
            const dx = stage.playerPos.x - this.sprite.x;
            this.sprite.horizontalFlip = dx < 0;
            this.spriteItems[0].tileIndex = 0x3d;
            this.spriteItems[1].tileIndex = 0x3f;
        } else {
            // 3b:39 37:35
            this.sprite.horizontalFlip = this.mode > 0;
            if (Math.ceil(this.clock / 6) & 1) {
                this.spriteItems[0].tileIndex = 0x35;
                this.spriteItems[1].tileIndex = 0x37;
            } else {
                this.spriteItems[0].tileIndex = 0x39;
                this.spriteItems[1].tileIndex = 0x3b;
            }
        }
    }
    protected onHit(manager: EnemyManager, _hit: HitTest): void {
        manager.remove(this).addBomb(this.sprite.x, this.sprite.y, "normal").addPoint(100);

    }
}
