export interface PpuMemoryAccessor {
    write(addr: number, value: number): void;
    read(addr: number): number;
    writeBytes(addr: number, data: Uint8Array): void;
    readBytes(addr: number, length: number): Uint8Array;
}

export interface INameTable extends PpuMemoryAccessor {
    print(x: number, y: number, data: string | Uint8Array | number[] | string[] | {
        data: Uint8Array | number[];
        width: number;
    }): INameTable;
    setColor(x: number, y: number, color: number): INameTable;
}

export interface IChrRom {
    set(bank: number): void;
}

export const SPRITE_VERTICAL_FLIP = 0x80;
export const SPRITE_HORIZONTAL_FLIP = 0x40;
export const SPRITE_BG_PRIORITY = 0x20;

export interface SpriteData {
    // 0-63
    index: number;
    y?: number;
    x?: number;
    tileIndex?: number;
    // VHP000CC
    attributes?: number;
    verticalFlip?: boolean;
    horizontalFlip?: boolean;
    bgPriority?: boolean;
    // 0-3
    paletteIndex?: number;
};

export interface PpuControllData {
    spriteSize?: 8 | 16;
    spritePatternTableIndex?: 0 | 1;
    bgPatternTableIndex?: 0 | 1;
    nameTableIndex?: 0 | 1 | 2 | 3;
    redEmphasis?: boolean;
    greenEmphasis?: boolean;
    blueEmphasis?: boolean;
    bgEnabled?: boolean;
    spriteEnabled?: boolean;
    spriteClippingDisabled?: boolean;
    bgClippingDisabled?: boolean;
}
export interface IPpuApi {
    getNameTable(index: number): INameTable;
    getPatternTable(index: number): PpuMemoryAccessor;
    getPalette(): PpuMemoryAccessor;
    setSpriteData(...data: SpriteData[]): IPpuApi;
    setScroll(x: number, y: number): IPpuApi;
    setMirrorMode(mirroring: 'horizontal' | 'vertical' | 'single0' | 'single1' | 'fourScreen'): IPpuApi;
    setControllData(...data: PpuControllData[]): IPpuApi;
    makeChrRom(rom: Uint8Array): IChrRom;
}

export const ButtonType = {
    A: 1,
    B: 2,
    SELECT: 4,
    START: 8,
    UP: 16,
    DOWN: 32,
    LEFT: 64,
    RIGHT: 128
};
export interface IPadApi {
    /**
     * 現在ボタンが押されているかどうか？
     * @param button 
     */
    isDown(button: number): number;
    /**
     * 前回のisPush以降に新たにボタンが押されたか？
     * @param button 
     */
    isPush(button: number): number;
}

export interface IGameMode {
    onEnter?(context: GameContext, prev?: IGameMode): void;
    /**
     * pushModeで呼び出される
     * @param context 
     * @param next 
     */
    onSuspend?(context: GameContext, next?: IGameMode): void;
    onResume?(context: GameContext, prev?: IGameMode): void;
    onLeave?(context: GameContext, next?: IGameMode): void;
    /**
     * onEnter,onResumeの次から呼び出される
     * @param context 
     * @param deltaFrame 
     */
    onUpdate?(context: GameContext, deltaFrame: number): void;
}
export interface IFamUtil {
    parseMemoryText(text: string): Map<string, Uint8Array>;
    setSaveData<T>(key: IDBValidKey, value: T): Promise<void>;
    getSaveData<T>(key: IDBValidKey): Promise<T | null>;
    deleteSaveData(key: IDBValidKey): Promise<void>;
}

export interface GameContext {
    ppu: IPpuApi;
    util: IFamUtil;
    setVBlankListener(listener: (ppu: IPpuApi) => void, scope?: string | string[]): GameContext;
    setHBlankListener(listener: (line: number, ppu: IPpuApi) => void, scope?: string | string[]): GameContext;
    clearListeners(scope?: string | string[]): GameContext;

    getPad(player: number): IPadApi | null;

    /**
     * モードを切り替える
     * 現状のListenerは全て破棄される
     * @param next 
     */
    moveMode(next: IGameMode): void;
    /**
     * 現在のモードを終了し、ゲームを終了またはPopする
     * 現状のListenerは全て破棄される
     */
    exitMode(): void;
    /**
     * モードを切り替えつつ、exitModeで戻るようにする
     * @param next 
     */
    pushMode(next: IGameMode): void;
}

export interface IFamRom {
    /**
     * 電源ONの初期化
     * @param context 
     */
    powerOn(context: GameContext): void;
    /**
     * 電源OFFの後処理
     */
    powerOff?(): void;
    /**
     * リセット（未実装ならpowerOnが呼ばれる）
     * @param context 
     */
    reset?(context: GameContext): void;
}

export type FamRomConstructor = new () => IFamRom;
export type FamRomEntry = {
    type: string;
    name: string;
    color: {
        text: string;
        side: string;
        face: string;
    };
    create: () => IFamRom;
};

// 各ROMスクリプトで初期化されるため、毎回 0 からカウントされる
let romNumber = 0;

export function RomEntry(name: string, color?: {
    text: string;
    side: string;
    face: string;
}) {
    romNumber++;
    return function <T extends FamRomConstructor>(target: T) {
        ((globalThis as any).famRomRegistry)({
            type: target.name + "_" + romNumber,
            name: name,
            color: color || {
                text: "#000000",
                side: "#4040ff",
                face: "#c0c0c0"
            },
            create: () => new target()
        });
    };
}