import { ButtonType, type GameContext, type IGameMode, type INameTable } from "../../src/types/plugin";
import { BombManager, chrRomMap, getTextCode, PowerCupsule, stageCharMap, writeSprites, type SpriteGroup } from "./common";
import { EnemyManager } from "./enemy";
import { StageEventManager, type StageEventData } from "./event";
import { PlayerData } from "./player";

const powerChars: { [id: string]: number[]; } = {
    speed: [9, 10, 11, 12],
    missle: [13, 14, 15, 16],
    double: [17, 18, 19, 20],
    laser: [21, 22, 23, 24],
    option: [25, 26, 27, 28],
    shield: [0x1d, 0x62, 0x63, 0x1f],
    space: [0x1d, 0x1e, 0x1e, 0x1f]
};

export class PlayMode implements IGameMode {
    private player: PlayerData;
    private spriteGroup: SpriteGroup[] = [];
    private event: StageEventManager;
    private enemy: EnemyManager;
    private cupsule: PowerCupsule;
    private bomber: BombManager;
    private pauseFlag: boolean;
    private stageData: StageEventData;

    public constructor(player: PlayerData, stage: StageEventData, start=0) {
        this.player = player;
        this.stageData = stage;
        this.event = new StageEventManager(stage, start);
        this.enemy = new EnemyManager();
        this.cupsule = new PowerCupsule();
        this.bomber = new BombManager();
        this.pauseFlag = false;
    }
    onEnter(context: GameContext, _prev?: IGameMode): void {
        context.ppu.setControllData({
            bgEnabled: true,
            spriteEnabled: true,
            nameTableIndex: 0,
        });
        for (let i = 2; i < 3; i++) {
            const name = context.ppu.getNameTable(0);
            for (let j = 0; j < 32; j++) {
                name.write(j, 0);
            }
        }
        this.spriteGroup = [this.cupsule.sprite, this.bomber.sprite, this.enemy.missle.sprite];
        this.player.initSprite(this.spriteGroup);
        context.ppu.getPalette().writeBytes(0, new Uint8Array([
            0x0f, 0x12, 0x30, 0x0f,
            0x0f, 0x27, 0x30, 0x0f,
            0x0f, 0x19, 0x2a, 0x30,
            0x0f, 0x07, 0x17, 0x26,
            0x0f, 0x0c, 0x26, 0x30,
            0x0f, 0x0c, 0x2c, 0x30,
            0x0f, 0x21, 0x26, 0x30,
            0x0f, 0x06, 0x26, 0x30
        ]));
        context.setHBlankListener((line, ppu) => {
            if (line === 211) {
                chrRomMap[1].set(0);
                ppu.setControllData({ nameTableIndex: 0 });
                ppu.setScroll(0, 12);
                /*
                chrRomMap[this.event.context.chrRomIndex].set(0);
                ppu.setControllData({ nameTableIndex: ((this.event.context.progress >> 8) & 1) as any });
                ppu.setScroll(this.event.context.progress & 255, 24);
                */
            } else if (this.event.context.frameChange.length > 0 && this.event.context.frameChange[0].line === line) {
                const dt = this.event.context.frameChange[0];
                ppu.setControllData({
                    nameTableIndex: dt.nameIndex
                });
                ppu.setScroll(dt.x, dt.y);
                this.event.context.frameChange.splice(0, 1);
            }
        });
        const name = context.ppu.getNameTable(0);
        this.drawPower(name, 0, "speed", false);
        this.drawPower(name, 1, "missle", false);
        this.drawPower(name, 2, "double", false);
        this.drawPower(name, 3, "laser", false);
        this.drawPower(name, 4, "option", false);
        this.drawPower(name, 5, "shield", false);
        this.drawScore(name);
    }
    private drawPower(name: INameTable, ix: number, key: string, focus: boolean): void {
        name.print(4 + ix * 4, 28, powerChars[key]);
        name.setColor(4 + ix * 4, 28, focus ? 1 : 0);
        name.setColor(6 + ix * 4, 28, focus ? 1 : 0);
    }
    private drawScore(name: INameTable): void {
        let text = "   @ 1  1P " + (new String(this.event.context.score)).padStart(7, '0') + "  HI " + (new String(this.event.context.hiScore)).padStart(7, '0') + "  ";
        name.print(0, 29, getTextCode(stageCharMap, text));
    }

    onUpdate(context: GameContext, _deltaFrame: number): void {
        const pad = context.getPad(0)!;
        let addScore = 0;
        if (!this.pauseFlag) {
            if (this.player.missCount > 240) {
                // 再実行
                context.moveMode(new PlayMode(new PlayerData(), this.stageData, this.event.context.progress));
                return;
            }
            this.event.stepFrame(context.ppu, this.player, this.enemy);
            // プレイヤー
            const hitTest = this.player.stepFrame(this.event.context, pad, this.spriteGroup);
            this.event.context.playerPos = {
                x: this.player.sprite.x,
                y: this.player.sprite.y
            };
            const plhit = hitTest[hitTest.length - 1];
            this.cupsule.stepFrame(this.event.context, plhit, clean => {
                if (clean) {
                    // 敵を全滅させる
                    hitTest.splice(0, 0, {
                        id: "erase",
                        x: 0,
                        y: 0,
                        width: 256,
                        height: 240,
                        type: "erase"
                    });
                } else {
                    addScore += 500;
                    this.player.onGetCupsule();
                }
            });
            // 敵
            this.enemy.stepFrame(this.event.context, this.spriteGroup, hitTest, (hit, enemy) => {
                return this.player.onHitTest(hit, enemy);
            });
            addScore += this.enemy.plusPoint;
            if (this.player.missCount === 1) {
                // ミスした
                const ix = this.spriteGroup.indexOf(this.player.sprite);
                if (ix >= 0) {
                    this.spriteGroup.splice(ix, 1);
                    this.bomber.addBomb(this.player.sprite.x, this.player.sprite.y, "player");
                }
            }
            this.enemy.cupsules.forEach(cp => this.cupsule.addCupsule(cp.x, cp.y));
            this.enemy.bombers.forEach(bom => this.bomber.addBomb(bom.x, bom.y, bom.type));
            this.bomber.stepFrame(this.event.context, plhit, () => { });
            // バリア
            if (this.player.barrierCount > 0) {
                // カプセルのspriteを利用
                let ch = 0xb7 + ((_deltaFrame & 4) >> 1) + ((_deltaFrame & 8) ? 10 : 0);
                this.cupsule.sprite.items.splice(0, 0, {
                    dx: this.player.sprite.x + 24,
                    dy: this.player.sprite.y,
                    attributes: this.player.barrierCount === 1 ? 0 : 1,
                    tileIndex: ch
                });
            }
        }
        writeSprites(context.ppu, this.spriteGroup);
        // 順番を入れ替える
        this.spriteGroup = [...this.spriteGroup.slice(1), this.spriteGroup[0]];

        const cupsule = ["speed", "missle", "double", "laser", "option", "shield"];
        const flag = this.player.getCupsuleFlag();
        const name = context.ppu.getNameTable(0);
        for (let x = 0; x < 32; x += 2) {
            name.setColor(x, 29, 0);
        }
        for (let i = 0; i < cupsule.length; i++) {
            this.drawPower(name, i, (flag & (1 << i)) ? cupsule[i] : "space", this.player.powerLevel === i + 1);
        }
        this.event.context.draw(context.ppu);
        if (this.pauseFlag) {
            if (pad.isPush(ButtonType.START)) {
                this.pauseFlag = false;
            }
            return;
        }
        if ((_deltaFrame & 127) === 0) {
            // TODO test
            this.cupsule.addCupsule(256, Math.floor(Math.random() * 144) + 24);
        }
        if (addScore > 0) {
            this.event.context.score += addScore;
            if (this.event.context.score > this.event.context.hiScore) {
                this.event.context.hiScore = this.event.context.score;
            }
            this.drawScore(context.ppu.getNameTable(0));
        }
        if (pad.isPush(ButtonType.START)) {
            this.pauseFlag = true;
        }
    }
}