import { SPRITE_BG_PRIORITY, SPRITE_HORIZONTAL_FLIP, SPRITE_VERTICAL_FLIP, type IChrRom, type IPpuApi, type SpriteData } from "../../src/types/plugin";

export let chrRomMap: IChrRom[] = [];

export type CodeMap = { [ch: string]: number; };

export interface HitTest {
    id: string;
    x: number;
    y: number;
    width: number;
    height: number;
    // ブロック衝突判定に使う座標
    block?: {
        x: number;
        y: number;
    };
    type: "missle" | "laser" | "player" | "barrier" | "erase";
}

export function makeCharMap(code: number, text: string): CodeMap {
    let map: { [chr: string]: number; } = {};
    for (let i = 0; i < text.length; i++) {
        map[text[i]] = code + i;
    }
    return map;
}

export function getTextCode(charMap: CodeMap, text: string): number[] {
    let ret: number[] = [];
    for (let i = 0; i < text.length; i++) {
        ret.push(charMap[text.charAt(i)] || 0)
    }
    return ret;
}

export interface SpriteItem {
    tileIndex: number;
    dx: number;
    dy: number;
    attributes: number;
};

export interface SpriteGroup {
    x: number;
    y: number;
    width?: number;     // あとで自動で入る
    height?: number;    // あとで自動で入る
    horizontalFlip: boolean;
    verticalFlip: boolean;
    items: SpriteItem[];
}

export function writeSprites(ppu: IPpuApi, groups: SpriteGroup[]): void {
    let index = 0;
    let count = 0;
    while (index < 64) {
        let flag = false;
        for (let group of groups) {
            if (count >= group.items.length) {
                continue;
            }
            if (!group.width) {
                group.width = Math.max(...group.items.map(itm => itm.dx)) + 8;
            }
            if (!group.height) {
                group.height = Math.max(...group.items.map(itm => itm.dy)) + 16;
            }
            const item = group.items[count];
            const spData: SpriteData = {
                index: index,
                tileIndex: item.tileIndex,
                x: group.x + (group.horizontalFlip ? (group.width - item.dx - 8) : item.dx),
                y: group.y + (group.verticalFlip ? (group.height - item.dy - 16) : item.dy),
                attributes: item.attributes ^ (group.horizontalFlip ? SPRITE_HORIZONTAL_FLIP : 0) ^ (group.verticalFlip ? SPRITE_VERTICAL_FLIP : 0)
            };
            flag = true;
            if (spData.x! <= 0 || spData.x! >= 256 || spData.y! < -16 || spData.y! >= 239) {
                continue;
            }
            index++;
            ppu.setSpriteData(spData);
            if (index >= 64) {
                break;
            }
        }
        if (!flag) {
            break;
        }
        count++;
    }
    // 非表示にする
    while (index < 64) {
        ppu.setSpriteData({
            index: index++,
            y: 239
        });
    }
}

