export interface LaserDraw {
    y: number;
    lines: {
        sx: number;
        ex: number;
    }[];
}

export class StageContext {
    progress: number;
    // 今回のStepでスクロールしたかどうか
    scroll: boolean;
    playerPos: {
        x: number;
        y: number;
    };
    chrRomIndex: number;
    blockFlags: number[][];
    bgText: string[];
    score: number;
    hiScore: number;
    laserDraw: LaserDraw[];
    frameChange: {
        line: number;
        nameIndex: 0 | 1 | 2 | 3;
        x: number;
        y: number;
    }[];

    public constructor() {
        this.progress = 0;
        this.laserDraw = [];
        this.frameChange = [];
        this.playerPos = { x: 72, y: 96 };
        this.scroll = false;
        this.chrRomIndex = 2;
        this.blockFlags = [];
        this.bgText = [];
        this.score = 0;
        this.hiScore = 0;
        for (let i = 0; i < 32; i++) {
            this.blockFlags.push(new Array(13).fill(0));
            this.bgText.push(String.fromCharCode(...(new Array(13).fill(0))));
            this.bgText.push(String.fromCharCode(...(new Array(13).fill(0))));
        }
    }
    public step(): void {
        this.scroll = !this.scroll;
        if (this.scroll) {
            this.progress++;
        }
    }
    public draw(ppu: IPpuApi): void {
        const nmix: any = (this.progress >> 8) & 1;
        const sx = this.progress & 255;
        chrRomMap[this.chrRomIndex].set(0);
        ppu.setControllData({
            nameTableIndex: nmix
        });
        ppu.setScroll(sx, 12);
        this.frameChange = [];
        this.laserDraw.forEach((ls, ix) => {
            this.drawLaser(ppu, ix, ls);
            const dt = {
                line: ls.y,
                nameIndex: nmix,
                x: sx,
                y: 240 + ix * 16 - ((ls.y + 5) & ~7) + 12
            };
            if (dt.y >= 240) {
                dt.y -= 240;
                dt.nameIndex += 2;
            }
            this.frameChange.push(dt);
            if (ix >= this.laserDraw.length - 1 || ls.y + 1 < this.laserDraw[ix + 1].y) {
                this.frameChange.push({
                    line: dt.line + 1,
                    nameIndex: nmix,
                    x: sx,
                    y: 12
                });
            }
        });
        this.laserDraw = [];
    }
    public drawLaser(ppu: IPpuApi, index: number, draw: LaserDraw): void {
        const slx = (this.progress >> 3) & 63;
        const elx = ((this.progress + 255 + 8) >> 3) & 63;
        let x = slx;
        let ly = (draw.y - 4 + 1) >> 3;
        let addr = index * 64 + 32;
        while (x !== elx) {
            const name = ppu.getNameTable((x & 32) ? 3 : 2);
            name.write(addr + (x & 31), this.bgText[x].charCodeAt(ly));
            name.setColor(x & 31, index * 2, this.blockFlags[x >> 1][ly >> 1] >> 4);
            x = (x + 1) & 63;
        }
        for (let dt of draw.lines) {
            const sx = ((dt.sx + this.progress + 7) >> 3) & 63;
            let ex = ((dt.ex + this.progress) >> 3) & 63;
            x = sx;
            if (sx === ex || sx === ((ex + 1) & 63) || sx === ((ex + 2) & 63)) {
                ex = (sx + 1) & 63;
            }
            while (x !== ex) {
                const name = ppu.getNameTable((x & 32) ? 3 : 2);
                name.write(addr + (x & 31), 0x3a);
                name.setColor(x & 31, index * 2, 2);
                x = (x + 1) & 63;
            }
        }
    }
    public addLaserDraw(draw: LaserDraw): void {
        if (draw.lines[0].ex <= draw.lines[0].sx) {
            return;
        }
        const old = this.laserDraw.find(dt => dt.y === draw.y);
        if (old) {
            old.lines.push(...draw.lines);
            // マージする
            old.lines.sort((v1, v2) => v1.sx - v2.sx);
            const newLines: { sx: number; ex: number; }[] = [];
            for (let dt of old.lines) {
                if (newLines.length === 0) {
                    newLines.push(dt);
                } else {
                    const last = newLines[newLines.length - 1];
                    if (dt.sx <= last.ex) {
                        // マージする
                        last.ex = Math.max(last.ex, dt.ex);
                    } else {
                        newLines.push(dt);
                    }
                }
            }
            old.lines = newLines;
        } else {
            this.laserDraw.push(draw);
            this.laserDraw.sort((v1, v2) => v1.y - v2.y);
        }
    }
    public isBlock(sx: number, sy: number): boolean {
        const bx = Math.floor((sx + this.progress) / 8) & 63;
        const by = Math.floor((sy - 9 + 4) / 8);
        const flag = this.blockFlags[bx >> 1][by >> 1];
        return (flag & (1 << ((bx & 1) | ((by & 1) << 1)))) > 0;
    }
    public getBlockChar(sx: number, sy: number): number {
        const bx = Math.floor((sx + this.progress) / 8) & 63;
        const by = Math.floor((sy - 8 + 4) / 8);
        return this.bgText[bx].charCodeAt(by);
    }
}

export abstract class RotateSpriteBase<T> {
    sprite: SpriteGroup;
    clock: number;

    protected constructor() {
        this.sprite = {
            x: 0,
            y: 0,
            horizontalFlip: false,
            verticalFlip: false,
            items: []
        };
        this.clock = 0;
    }

    public stepFrame(stage: StageContext, hit: HitTest, callback: (param: T) => void): void {
        this.clock++;
        const items = this.onStep(stage, hit, callback);
        this.sprite.items = items.map((_itm, ix) => items[(ix + this.clock) % items.length]);
    }
    protected abstract onStep(stage: StageContext, hit: HitTest, callback: (param: T) => void): SpriteItem[];
}

export class PowerCupsule extends RotateSpriteBase<boolean> {
    cupsules: {
        x: number;
        y: number;
        clean: boolean;
    }[] = [];
    dropCount: number;

    public constructor() {
        super();
        this.dropCount = 0;
    }

    protected onStep(stage: StageContext, hit: HitTest, callback: (clean: boolean) => void): SpriteItem[] {
        const items: SpriteItem[] = [];
        this.cupsules = this.cupsules.filter(cp => {
            if (hit) {
                if (cp.x < hit.x + hit.width && hit.x < cp.x + 16 && cp.y < hit.y + hit.height && hit.y < cp.y + 16) {
                    // Hit
                    callback(cp.clean);
                    return false;
                }
            }
            if (stage.scroll) {
                cp.x--;
                if (cp.x <= -8) {
                    // 画面範囲外
                    return false;
                }
            }

            // 5d,*5d,5f
            const pal = cp.clean ? 1 : 3;
            let ch = 0x5d;
            let attr1 = SPRITE_VERTICAL_FLIP;
            let attr2 = 0;
            switch (Math.floor(this.clock / 6) % 3) {
                case 0:
                    attr1 = 0;
                    attr2 = SPRITE_VERTICAL_FLIP;
                    break;
                case 1:
                    break;
                default:
                    ch = 0x5f;
                    break;
            }
            items.push({
                dx: cp.x,
                dy: cp.y,
                attributes: pal | SPRITE_BG_PRIORITY | attr1,
                tileIndex: ch
            }, {
                dx: cp.x + 8,
                dy: cp.y,
                attributes: pal | SPRITE_BG_PRIORITY | SPRITE_HORIZONTAL_FLIP | attr2,
                tileIndex: ch
            });
            return true;
        });
        return items;
    }

    public addCupsule(x: number, y: number): void {
        this.dropCount++;
        this.cupsules.push({ x, y, clean: (this.dropCount & 15) === 0 });
    }
}

