export class BombManager extends RotateSpriteBase<void> {
    bombList: {
        x: number;
        y: number;
        type: "player" | "small" | "normal" | "large";
        time: number;
    }[] = [];
    public constructor() {
        super();
    }
    protected onStep(stage: StageContext, _hit: HitTest, _callback: () => void): SpriteItem[] {
        const items: SpriteItem[] = [];
        this.bombList = this.bombList.filter(bom => {
            if (stage.scroll) {
                bom.x--;
            }
            const data = bombData[bom.type];
            let ix = Math.floor(bom.time / data.frame);
            if (ix >= data.itemList.length) {
                // 終了
                return false;
            }
            items.push(...data.itemList[ix].map(dt => ({
                dx: dt.dx + bom.x,
                dy: dt.dy + bom.y,
                attributes: dt.attributes,
                tileIndex: dt.tileIndex
            })));
            bom.time++;
            return true;
        });
        return items;
    }
    public addBomb(x: number, y: number, type: "player" | "small" | "normal" | "large"): void {
        this.bombList.push({
            x: x,
            y: y,
            type: type,
            time: 0
        });
    }
}

